SET search_path=hvb,public;
-- Alta/saída retroativa preserva o relato original e expõe divergência para revisão.
CREATE OR REPLACE VIEW evolucao_clinica_versao_consulta WITH(security_invoker=true) AS SELECT v.id,v.organizacao_id,v.unidade_id,v.autor_id,v.comando_id,v.motivo,v.criada_em,v.evolucao_id,v.versao,v.anterior_id,v.estado,v.ocorrida_em,v.hash_conteudo,e.paciente_id,e.episodio_id,e.tipo,NOT EXISTS(SELECT 1 FROM evolucao_clinica_versao n WHERE n.organizacao_id=v.organizacao_id AND n.evolucao_id=v.evolucao_id AND n.versao>v.versao) AS atual,v.estado='registrada' AND (v.ocorrida_em<p.admitido_em OR v.ocorrida_em>coalesce(p.encerrado_em,p.alta_clinica_em,'infinity'::timestamptz)) AS revisao_temporal FROM evolucao_clinica_versao v JOIN evolucao_clinica e ON e.organizacao_id=v.organizacao_id AND e.id=v.evolucao_id JOIN episodio p ON p.organizacao_id=e.organizacao_id AND p.id=e.episodio_id;
